package com.ccp.aop;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

/**
 * Reads, for {@code CcpToStringBuilder}, the instance attributes declared in a class and in its superclasses (except
 * Object). Static and synthetic ones are left out: the former are class state, not object state, and the latter are
 * generated by the compiler or by instrumentation (this$0, $jacocoData).
 */
public class CcpInstanceFieldsReader implements Function<Class<?>, List<Field>> {

	/** The only instance: the reader keeps no state. */
	public final static CcpInstanceFieldsReader INSTANCE = new CcpInstanceFieldsReader();

	private CcpInstanceFieldsReader() {
	}

	/**
	 * Reads the instance attributes of the class.
	 * @param clazz the class
	 * @return the accessible instance attributes, subclass first
	 */
	public List<Field> apply(Class<?> clazz) {
		List<Field> fields = new ArrayList<>();
		for (Class<?> current = clazz; current != null && current != Object.class; current = current.getSuperclass()) {
			Field[] declaredFields = current.getDeclaredFields();
			for (Field field : declaredFields) {
				boolean synthetic = field.isSynthetic();
				boolean isSyntheticOrStatic = synthetic || Modifier.isStatic(field.getModifiers());
				if (isSyntheticOrStatic) {
					continue;
				}
				try {
					field.setAccessible(true);
				} catch (RuntimeException e) {
					continue;
				}
				fields.add(field);
			}
		}
		return fields;
	}
}
